while (infile.read(&bit, 1)) {
    std::shared_ptr<Node> current = root;

    // Read the path to the leaf
    while (true) {
        char direction;
        infile.read(&direction, 1);

        if (direction == '0') {
            if (!current->left) {
                current->left = std::make_shared<Node>();
            }
            current = current->left;
        } else if (direction == '1') {
            if (!current->right) {
                current->right = std::make_shared<Node>();
            }
            current = current->right;
        }

        // Check if we reached a leaf marker (assuming a specific marker or length)
        // In a standard Huffman binary dictionary format, a '1' or specific 
        // character often denotes the end of the path followed by the actual value.
        // Assuming the format: [path bits...][leaf marker][character value]
        if (direction == 'L') { // Example leaf marker
            break;
        }
    }

    char value;
    infile.read(&value, 1);
    current->value = value;
    current->is_leaf = true;
}
